window.aulaGrammar21=[{"id":"t4","topicNumber":"04","title":"Diftongs i hiats","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t4-ex1","number":"04.1","title":"Diftongs, hiats i separació sil·làbica","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Per a cada mot:</p><ol><li>Identifica els grups de vocals i indica si formen diftong decreixent, diftong creixent o hiat.</li><li>Escriu-lo i separa’l en síl·labes.</li><li>Indica quina és la síl·laba tònica.</li><li>Afegeix els accents que calguin.</li><li>Passa els resultats al quadre de classificació de l’exercici següent.</li></ol><p>Al quadern s’utilitzen colors i subratllats. Aquí pots escriure la classificació i la tònica al costat de la paraula. Un mot pot contenir més d’un fenomen.</p>","responseFields":[{"label":"1","question":"mai"},{"label":"2","question":"viatge"},{"label":"3","question":"avio"},{"label":"4","question":"remei"},{"label":"5","question":"quatre"},{"label":"6","question":"cuina"},{"label":"7","question":"treure"},{"label":"8","question":"accio"},{"label":"9","question":"riure"},{"label":"10","question":"cua"},{"label":"11","question":"pasqües"},{"label":"12","question":"dues"},{"label":"13","question":"guanyar"},{"label":"14","question":"niu"},{"label":"15","question":"cau"},{"label":"16","question":"religio"},{"label":"17","question":"dies"},{"label":"18","question":"reu"},{"label":"19","question":"afectuos"},{"label":"20","question":"poeta"},{"label":"21","question":"afaitar"},{"label":"22","question":"creu"},{"label":"23","question":"divuit"},{"label":"24","question":"cinquanta"},{"label":"25","question":"coure"},{"label":"26","question":"aire"},{"label":"27","question":"hereu"},{"label":"28","question":"heroi"},{"label":"29","question":"suor"},{"label":"30","question":"heura"},{"label":"31","question":"historia"},{"label":"32","question":"avui"},{"label":"33","question":"herencia"},{"label":"34","question":"havia"},{"label":"35","question":"avia"},{"label":"36","question":"quadre"},{"label":"37","question":"roure"},{"label":"38","question":"biografia"},{"label":"39","question":"guany"},{"label":"40","question":"llengua"},{"label":"41","question":"llengües"},{"label":"42","question":"llaurar"},{"label":"43","question":"Equador"},{"label":"44","question":"lliure"},{"label":"45","question":"conreu"},{"label":"46","question":"quantitat"},{"label":"47","question":"zoològic"},{"label":"48","question":"ioga"},{"label":"49","question":"estacio"},{"label":"50","question":"avaluacio"},{"label":"51","question":"rei"},{"label":"52","question":"teatre"},{"label":"53","question":"guardar"},{"label":"54","question":"feina"},{"label":"55","question":"llauna"},{"label":"56","question":"il·lusio"},{"label":"57","question":"pingüí"},{"label":"58","question":"aigua"},{"label":"59","question":"Maria"},{"label":"60","question":"iogurt"},{"label":"61","question":"ciutat"},{"label":"62","question":"peu"},{"label":"63","question":"aire"},{"label":"64","question":"lluitar"}],"solutionHtml":"<ul><li>mai: mai; tònica: mai; diftong decreixent.</li><li>viatge: vi-at-ge; tònica: at; hiat.</li><li>avió: a-vi-ó; tònica: ó; hiat.</li><li>remei: re-mei; tònica: mei; diftong decreixent.</li><li>quatre: qua-tre; tònica: qua; diftong creixent amb gu/qu.</li><li>cuina: cui-na; tònica: cui; diftong decreixent.</li><li>treure: treu-re; tònica: treu; diftong decreixent.</li><li>acció: ac-ci-ó; tònica: ó; hiat.</li><li>riure: riu-re; tònica: riu; diftong decreixent.</li><li>cua: cu-a; tònica: cu; hiat.</li><li>pasqües: pas-qües; tònica: pas; diftong creixent amb gu/qu.</li><li>dues: du-es; tònica: du; hiat.</li><li>guanyar: gua-nyar; tònica: nyar; diftong creixent amb gu/qu.</li><li>niu: niu; tònica: niu; diftong decreixent.</li><li>cau: cau; tònica: cau; diftong decreixent.</li><li>religió: re-li-gi-ó; tònica: ó; hiat.</li><li>dies: di-es; tònica: di; hiat.</li><li>reu: reu; tònica: reu; diftong decreixent.</li><li>afectuós: a-fec-tu-ós; tònica: ós; hiat.</li><li>poeta: po-e-ta; tònica: e; hiat.</li><li>afaitar: a-fai-tar; tònica: tar; diftong decreixent.</li><li>creu: creu; tònica: creu; diftong decreixent.</li><li>divuit: di-vuit; tònica: vuit; diftong decreixent.</li><li>cinquanta: cin-quan-ta; tònica: quan; diftong creixent amb gu/qu.</li><li>coure: cou-re; tònica: cou; diftong decreixent.</li><li>aire: ai-re; tònica: ai; diftong decreixent.</li><li>hereu: he-reu; tònica: reu; diftong decreixent.</li><li>heroi: he-roi; tònica: roi; diftong decreixent.</li><li>suor: su-or; tònica: or; hiat.</li><li>heura: heu-ra; tònica: heu; diftong decreixent.</li><li>història: his-tò-ri-a; tònica: tò; hiat.</li><li>avui: a-vui; tònica: vui; diftong decreixent.</li><li>herència: he-rèn-ci-a; tònica: rèn; hiat.</li><li>havia: ha-vi-a; tònica: vi; hiat.</li><li>àvia: à-vi-a; tònica: à; hiat.</li><li>quadre: qua-dre; tònica: qua; diftong creixent amb gu/qu.</li><li>roure: rou-re; tònica: rou; diftong decreixent.</li><li>biografia: bi-o-gra-fi-a; tònica: fi; hiat.</li><li>guany: guany; tònica: guany; diftong creixent amb gu/qu.</li><li>llengua: llen-gua; tònica: llen; diftong creixent amb gu/qu.</li><li>llengües: llen-gües; tònica: llen; diftong creixent amb gu/qu.</li><li>llaurar: llau-rar; tònica: rar; diftong decreixent.</li><li>Equador: E-qua-dor; tònica: dor; diftong creixent amb gu/qu.</li><li>lliure: lliu-re; tònica: lliu; diftong decreixent.</li><li>conreu: con-reu; tònica: reu; diftong decreixent.</li><li>quantitat: quan-ti-tat; tònica: tat; diftong creixent amb gu/qu.</li><li>zoològic: zo-o-lò-gic; tònica: lò; hiat.</li><li>ioga: io-ga; tònica: io; i consonàntica.</li><li>estació: es-ta-ci-ó; tònica: ó; hiat.</li><li>avaluació: a-va-lu-a-ci-ó; tònica: ó; hiat.</li><li>rei: rei; tònica: rei; diftong decreixent.</li><li>teatre: te-a-tre; tònica: a; hiat.</li><li>guardar: guar-dar; tònica: dar; diftong creixent amb gu/qu.</li><li>feina: fei-na; tònica: fei; diftong decreixent.</li><li>llauna: llau-na; tònica: llau; diftong decreixent.</li><li>il·lusió: il·lu-si-ó; tònica: ó; hiat.</li><li>pingüí: pin-güí; tònica: güí; diftong creixent amb gu/qu.</li><li>aigua: ai-gua; tònica: ai; diftong decreixent ai i diftong creixent ua amb g.</li><li>Maria: Ma-ri-a; tònica: ri; hiat.</li><li>iogurt: io-gurt; tònica: gurt; i consonàntica.</li><li>ciutat: ciu-tat; tònica: tat; diftong decreixent.</li><li>peu: peu; tònica: peu; diftong decreixent.</li><li>aire: ai-re; tònica: ai; diftong decreixent.</li><li>lluitar: llui-tar; tònica: tar; diftong decreixent.</li></ul>"},{"id":"t4-ex2","number":"04.2","title":"Quadre de classificació","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Diftongs decreixents"},{"label":"2","question":"Diftongs creixents amb gu/qu"},{"label":"3","question":"I o u consonàntiques"},{"label":"4","question":"Hiats"}],"solutionHtml":"<ul><li>Decreixents: mai, remei, cuina, treure, riure, niu, cau, reu, afaitar, creu, divuit, coure, aire, hereu, heroi, heura, avui, roure, llaurar, lliure, conreu, rei, feina, llauna, ciutat, peu, lluitar; també ai d’aigua.</li><li>Creixents: quatre, pasqües, guanyar, cinquanta, quadre, guany, llengua, llengües, Equador, quantitat, guardar, pingüí, aigua.</li><li>I consonàntica: ioga, iogurt.</li><li>Hiats: viatge, avió, acció, cua, dues, religió, dies, afectuós, poeta, suor, història, herència, havia, àvia, biografia, zoològic, estació, avaluació, teatre, il·lusió, Maria.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Un diftong agrupa dues vocals en una mateixa síl·laba. Un hiat separa les vocals en síl·labes diferents.</li><li>Els diftongs decreixents acaben en i o u. Els creixents apareixen en els grups gu/qu amb u pronunciada i en determinades combinacions amb i/u consonàntiques.</li><li>Separa les síl·labes abans d’aplicar les regles d’accentuació.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>ai-re</li><li>qua-tre</li><li>no-ia</li><li>a-e-ro-port</li><li>à-vi-a</li><li>Ma-ri-a</li></ul></div></section>"},{"id":"t5","topicNumber":"05","title":"La dièresi","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t5-ex1","number":"05.1","title":"Accents, dièresis i classificació","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Escriu la forma correcta i explica si la dièresi indica una u pronunciada, un hiat o una i vocàlica entre vocals. Indica també els mots que no necessiten dièresi.</p>","responseFields":[{"label":"1","question":"aquari"},{"label":"2","question":"frequent"},{"label":"3","question":"lingüística"},{"label":"4","question":"aigues"},{"label":"5","question":"conduien"},{"label":"6","question":"qualificar"},{"label":"7","question":"riu"},{"label":"8","question":"pingui"},{"label":"9","question":"llengua"},{"label":"10","question":"Raul"},{"label":"11","question":"produit"},{"label":"12","question":"Lluisa"},{"label":"13","question":"enquesta"},{"label":"14","question":"aigua"},{"label":"15","question":"Lluis"},{"label":"16","question":"heroi"},{"label":"17","question":"Pasqua"},{"label":"18","question":"Pasques"},{"label":"19","question":"Mireia"},{"label":"20","question":"quatre"},{"label":"21","question":"questio"},{"label":"22","question":"Suissa"},{"label":"23","question":"Suis"},{"label":"24","question":"reina"},{"label":"25","question":"sequencia"},{"label":"26","question":"vei"},{"label":"27","question":"consequencia"},{"label":"28","question":"llengues"},{"label":"29","question":"reia"},{"label":"30","question":"hereu"},{"label":"31","question":"veia"},{"label":"32","question":"conduit"}],"solutionHtml":"<ul><li>aquari: sense dièresi ni accent afegit.</li><li>freqüent: la u es pronuncia; aplica també l’accent si correspon.</li><li>lingüística: la u es pronuncia; aplica també l’accent si correspon.</li><li>aigües: la u es pronuncia; aplica també l’accent si correspon.</li><li>conduïen: la i entre vocals forma síl·laba: con-du-ï-en.</li><li>qualificar: sense dièresi ni accent afegit.</li><li>riu: sense dièresi ni accent afegit.</li><li>pingüí: la u es pronuncia; aplica també l’accent si correspon.</li><li>llengua: sense dièresi ni accent afegit.</li><li>Raül: dièresi de hiat.</li><li>produït: dièresi de hiat.</li><li>Lluïsa: dièresi de hiat.</li><li>enquesta: sense dièresi ni accent afegit.</li><li>aigua: sense dièresi ni accent afegit.</li><li>Lluís: hiat amb accent; no s’hi posa dièresi.</li><li>heroi: sense dièresi ni accent afegit.</li><li>Pasqua: sense dièresi ni accent afegit.</li><li>Pasqües: la u es pronuncia; aplica també l’accent si correspon.</li><li>Mireia: sense dièresi ni accent afegit.</li><li>quatre: sense dièresi ni accent afegit.</li><li>qüestió: la u es pronuncia; aplica també l’accent si correspon.</li><li>Suïssa: dièresi de hiat.</li><li>suís: hiat amb accent; no s’hi posa dièresi.</li><li>reina: sense dièresi ni accent afegit.</li><li>seqüència: la u es pronuncia; aplica també l’accent si correspon.</li><li>veí: hiat amb accent; no s’hi posa dièresi.</li><li>conseqüència: la u es pronuncia; aplica també l’accent si correspon.</li><li>llengües: la u es pronuncia; aplica també l’accent si correspon.</li><li>reia: sense dièresi ni accent afegit.</li><li>hereu: sense dièresi ni accent afegit.</li><li>veia: sense dièresi ni accent afegit.</li><li>conduït: dièresi de hiat.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>La dièresi sobre la u indica que es pronuncia en güe, güi, qüe i qüi.</li><li>També indica un hiat en casos com veïna o una i vocàlica entre vocals, com conduïen.</li><li>Quan correspon un accent gràfic, aquest té prioritat: veí, Lluís. Hi ha excepcions a l’ús de la dièresi, com els infinitius en -ir i els gerundis corresponents.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>qüestió</li><li>aigües</li><li>veí / veïna</li><li>beneïa</li></ul></div></section>"},{"id":"t6","topicNumber":"06","title":"Les lletres B i V","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t6-ex1","number":"06.1","title":"Historieta amb B/V","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Escriu una historieta amb un mínim de 15 paraules que continguin b o v."}],"solutionHtml":"<ul><li>Model: L’avi vivia en un poble de la vall. Cada vespre obria la biblioteca i buscava un llibre. La veïna arribava amb bicicleta, bevia aigua i observava una vaca blanca. Després conversaven sobre el viatge i el bon temps.</li></ul>"},{"id":"t6-ex2","number":"06.2","title":"Continuem una història en imperfet","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Continua «Ahir, mentre estudiava…» amb un mínim de 10 verbs acabats en -ava."}],"solutionHtml":"<ul><li>Model: Ahir, mentre estudiava, escoltava música, mirava els apunts, buscava exemples, anotava dubtes i repassava les regles. La mare cuinava, el pare treballava, el germà dibuixava i la veïna cantava.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Escrivim b davant de l/r i, habitualment, darrere de m. Excepcions: tramvia, circumval·lació, triumvir.</li><li>Escrivim v darrere de n i en l’imperfet dels verbs de la primera conjugació.</li><li>Les famílies de mots poden alternar p/b o u/v. Algunes parelles canvien de significat segons b/v.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>llop → lloba</li><li>blau → blava</li><li>cantava, cantaves, cantàvem</li><li>baca / vaca</li><li>baga / vaga</li><li>ball / vall</li><li>bell / vell</li><li>bena / vena</li><li>beure / veure</li><li>bola / vola</li><li>buit / vuit</li><li>bull / vull</li></ul></div><h3>Diferències entre català i castellà</h3><div class=\"table-wrap\"><table><thead><tr><th>Català</th><th>Castellà</th></tr></thead><tbody><tr><td>mòbil</td><td>móvil</td></tr><tr><td>Àlaba</td><td>Álava</td></tr><tr><td>baf</td><td>vaho</td></tr><tr><td>País Basc</td><td>País Vasco</td></tr><tr><td>oblidar</td><td>olvidar</td></tr><tr><td>aprovar</td><td>aprobar</td></tr><tr><td>govern</td><td>gobierno</td></tr><tr><td>avorriment</td><td>aburrimiento</td></tr><tr><td>avi</td><td>abuelo</td></tr></tbody></table></div></section>"},{"id":"t7","topicNumber":"07","title":"L’apòstrof i les contraccions","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t7-ex1","number":"07.1","title":"Exemples d’apostrofació","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Busca cinc exemples amb el/la apostrofats."},{"label":"2","question":"Escriu exemples de les excepcions: i/u àtones, noms de lletres, la una, i/u consonàntiques i casos convencionals."},{"label":"3","question":"Busca cinc exemples amb de apostrofat."}],"solutionHtml":"<ul><li>l’home, l’arbre, l’illa, l’ungla, l’hora.</li><li>la universitat; la essa; la una; la iaia; la ira.</li><li>d’aigua, d’aire, d’història, d’hivern, d’oli.</li></ul>"},{"id":"t7-ex2","number":"07.2","title":"Les contraccions","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Escriu la contracció i un exemple.</p>","responseFields":[{"label":"1","question":"a + el"},{"label":"2","question":"a + els"},{"label":"3","question":"de + el"},{"label":"4","question":"de + els"},{"label":"5","question":"per + el"},{"label":"6","question":"per + els"},{"label":"7","question":"ca + el"},{"label":"8","question":"ca + els"},{"label":"9","question":"ca + en"}],"solutionHtml":"<ul><li>al poble</li><li>als pobles</li><li>del poble</li><li>dels pobles</li><li>pel carrer</li><li>pels carrers</li><li>cal metge</li><li>cals avis</li><li>can Joan</li></ul>"},{"id":"t7-ex3","number":"07.3","title":"L’article davant del nom","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"intel·ligència"},{"label":"2","question":"ull"},{"label":"3","question":"ídol"},{"label":"4","question":"anormalitat"},{"label":"5","question":"ús"},{"label":"6","question":"essa"},{"label":"7","question":"ira"},{"label":"8","question":"Isabel"},{"label":"9","question":"interès"},{"label":"10","question":"illa"},{"label":"11","question":"iaia"},{"label":"12","question":"ungla"},{"label":"13","question":"higiene"},{"label":"14","question":"unió"},{"label":"15","question":"humitat"},{"label":"16","question":"hivern"},{"label":"17","question":"injecció"},{"label":"18","question":"idea"},{"label":"19","question":"instància"},{"label":"20","question":"urna"},{"label":"21","question":"hisenda"},{"label":"22","question":"Irene"},{"label":"23","question":"italiana"},{"label":"24","question":"única"},{"label":"25","question":"instal·lació"},{"label":"26","question":"història"},{"label":"27","question":"erra"},{"label":"28","question":"asimetria"},{"label":"29","question":"infermera"},{"label":"30","question":"humiliació"},{"label":"31","question":"historiador"},{"label":"32","question":"una i altra"},{"label":"33","question":"hàmster"},{"label":"34","question":"humanitat"}],"solutionHtml":"<ul><li>la intel·ligència</li><li>l’ull</li><li>l’ídol</li><li>la anormalitat</li><li>l’ús</li><li>la essa</li><li>la ira</li><li>la Isabel</li><li>l’interès</li><li>l’illa</li><li>la iaia</li><li>l’ungla</li><li>la higiene</li><li>la unió</li><li>la humitat</li><li>l’hivern</li><li>la injecció</li><li>la idea</li><li>la instància</li><li>l’urna</li><li>la hisenda</li><li>la Irene</li><li>la italiana</li><li>l’única</li><li>la instal·lació</li><li>la història</li><li>la erra</li><li>la asimetria</li><li>la infermera</li><li>la humiliació</li><li>l’historiador</li><li>l’una i l’altra</li><li>el hàmster</li><li>la humanitat</li></ul>"},{"id":"t7-ex4","number":"07.4","title":"Del plural al singular","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"les ungles"},{"label":"2","question":"els ianquis"},{"label":"3","question":"les importàncies"},{"label":"4","question":"els hospitals"},{"label":"5","question":"les innovacions"},{"label":"6","question":"els humoristes"}],"solutionHtml":"<ul><li>l’ungla</li><li>el ianqui</li><li>la importància</li><li>l’hospital</li><li>la innovació</li><li>l’humorista</li></ul>"},{"id":"t7-ex5","number":"07.5","title":"AL, A LA o A L’","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"He telefonat ___ Enric."},{"label":"2","question":"Vivia ___ dia."},{"label":"3","question":"Ha nascut ___ una en punt."},{"label":"4","question":"Ho vaig vendre ___ encarregat."},{"label":"5","question":"Pregunta-ho ___ Isabel."},{"label":"6","question":"Tinc una brossa ___ ull."}],"solutionHtml":"<ul><li>a l’Enric</li><li>al dia</li><li>a la una</li><li>a l’encarregat</li><li>a la Isabel</li><li>a l’ull</li></ul>"},{"id":"t7-ex6","number":"07.6","title":"DEL, DE LA o DE L’","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"No hi entrava la llum ___ sol."},{"label":"2","question":"Han votat el candidat ___ esquerra."},{"label":"3","question":"Ens hem reunit a casa ___ Andreu."},{"label":"4","question":"Han marxat ___ urbanització."},{"label":"5","question":"Ara arriba el secretari ___ institut."},{"label":"6","question":"Sembla que vingues ___ hort."}],"solutionHtml":"<ul><li>del sol</li><li>de l’esquerra</li><li>de l’Andreu</li><li>de la urbanització</li><li>de l’institut</li><li>de l’hort</li></ul>"},{"id":"t7-ex7","number":"07.7","title":"PEL, PER LA o PER L’","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"L’hem conegut ___ esquena."},{"label":"2","question":"Les estrelles brillen ___ univers."},{"label":"3","question":"Et canvie aquest ___ altre."},{"label":"4","question":"Es preocupen ___ instal·lació elèctrica."},{"label":"5","question":"L’han buscat ___ illa i no el troben."},{"label":"6","question":"Conduïa ___ autopista."}],"solutionHtml":"<ul><li>per l’esquena</li><li>per l’univers</li><li>per l’altre</li><li>per la instal·lació</li><li>per l’illa</li><li>per l’autopista</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>El i la s’apostrofen habitualment davant de vocal o h muda. La no s’apostrofa davant de i/u àtones.</li><li>No apostrofem davant de i/u consonàntiques, en els noms de les lletres ni en la una (hora). Alguns casos convencionals són la ira, la anormalitat i la asimetria.</li><li>De s’apostrofa davant de vocal o h muda. Les contraccions al, del i pel es desfan si l’article es pot apostrofar.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>l’arbre</li><li>la universitat</li><li>la iaia</li><li>d’història</li><li>al poble / a l’institut</li><li>del parc / de l’aeroport</li></ul></div></section>"},{"id":"t8","topicNumber":"08","title":"Els números","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t8-ex1","number":"08.1","title":"Escriu els nombres en lletres","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"0"},{"label":"2","question":"1"},{"label":"3","question":"2"},{"label":"4","question":"3"},{"label":"5","question":"4"},{"label":"6","question":"5"},{"label":"7","question":"6"},{"label":"8","question":"7"},{"label":"9","question":"8"},{"label":"10","question":"9"},{"label":"11","question":"10"},{"label":"12","question":"11"},{"label":"13","question":"12"},{"label":"14","question":"13"},{"label":"15","question":"14"},{"label":"16","question":"15"},{"label":"17","question":"16"},{"label":"18","question":"17"},{"label":"19","question":"18"},{"label":"20","question":"19"},{"label":"21","question":"20"},{"label":"22","question":"21"},{"label":"23","question":"22"},{"label":"24","question":"23"},{"label":"25","question":"24"},{"label":"26","question":"25"},{"label":"27","question":"26"},{"label":"28","question":"27"},{"label":"29","question":"28"},{"label":"30","question":"29"},{"label":"31","question":"31"}],"solutionHtml":"<ul><li>0: zero</li><li>1: u</li><li>2: dos</li><li>3: tres</li><li>4: quatre</li><li>5: cinc</li><li>6: sis</li><li>7: set</li><li>8: vuit</li><li>9: nou</li><li>10: deu</li><li>11: onze</li><li>12: dotze</li><li>13: tretze</li><li>14: catorze</li><li>15: quinze</li><li>16: setze</li><li>17: disset</li><li>18: divuit</li><li>19: dinou</li><li>20: vint</li><li>21: vint-i-u</li><li>22: vint-i-dos</li><li>23: vint-i-tres</li><li>24: vint-i-quatre</li><li>25: vint-i-cinc</li><li>26: vint-i-sis</li><li>27: vint-i-set</li><li>28: vint-i-vuit</li><li>29: vint-i-nou</li><li>31: trenta-u</li></ul>"},{"id":"t8-ex2","number":"08.2","title":"Desenes, centenes i milers","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"10"},{"label":"2","question":"80"},{"label":"3","question":"31"},{"label":"4","question":"30"},{"label":"5","question":"90"},{"label":"6","question":"200"},{"label":"7","question":"40"},{"label":"8","question":"100"},{"label":"9","question":"2.000"},{"label":"10","question":"50"},{"label":"11","question":"1.000"},{"label":"12","question":"42"},{"label":"13","question":"60"},{"label":"14","question":"10.000"},{"label":"15","question":"54"},{"label":"16","question":"70"},{"label":"17","question":"1.000.000"},{"label":"18","question":"98"}],"solutionHtml":"<ul><li>deu</li><li>vuitanta</li><li>trenta-u</li><li>trenta</li><li>noranta</li><li>dos-cents</li><li>quaranta</li><li>cent</li><li>dos mil</li><li>cinquanta</li><li>mil</li><li>quaranta-dos</li><li>seixanta</li><li>deu mil</li><li>cinquanta-quatre</li><li>setanta</li><li>un milió</li><li>noranta-vuit</li></ul>"},{"id":"t8-ex3","number":"08.3","title":"Un premi de loteria","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Quants diners t’agradaria guanyar? Escriu la xifra i després escriu-la en lletres."}],"solutionHtml":"<p>Model: 250.000 euros → dos-cents cinquanta mil euros.</p>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>La regla D-U-C indica guionet entre desenes i unitats i entre unitats i centenes.</li><li>Del vint-i-u al vint-i-nou s’escriu i entre guionets. Les centenes concorden amb el nom.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>trenta-dos</li><li>dos-cents</li><li>dues-centes peres</li><li>un milió tres-centes vint-i-cinc mil sis-centes vuitanta-quatre peres</li></ul></div></section>"},{"id":"t9","topicNumber":"09","title":"J/G, TJ/TG i IG","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t9-ex1","number":"09.1","title":"Sèries i exemples","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Completa JA, ___, GI, ___, JU i posa un exemple de cada."},{"label":"2","question":"Completa GA, ___, ___, GO, ___ i posa exemples."},{"label":"3","question":"Completa GUA, ___, ___, GUO i posa exemples."}],"solutionHtml":"<ul><li>ja, ge, gi, jo, ju: jaqueta, gel, girafa, joc, jutge.</li><li>ga, gue, gui, go, gu: gat, guerra, guitarra, got, gust.</li><li>gua, güe, güi, guo: guant, aigües, pingüí, aiguota.</li></ul>"},{"id":"t9-ex2","number":"09.2","title":"Quadre de J/G i TJ/TG","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"J: vocals habituals i exemples."},{"label":"2","question":"G: vocals habituals i excepcions amb j."},{"label":"3","question":"TJ: vocals i exemples."},{"label":"4","question":"TG: vocals i exemples en -atge i -etge."}],"solutionHtml":"<ul><li>J davant de a, o, u: jaqueta, joc, just.</li><li>G davant de e, i: gel, girafa. Excepcions amb j: Jesús, Jeremies, jerarquia, jersei, subjecte, injecció, jeure.</li><li>TJ davant de a, o, u: platja, pitjor, jutjar.</li><li>TG davant de e, i: viatge, formatge, metge, fetge, jutgi.</li></ul>"},{"id":"t9-ex3","number":"09.3","title":"Completa les famílies de paraules","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa amb j/g o tj/tg. Escriu les dues formes de cada parella i conserva la grafia simple o el dígraf dins de la família.</p>","responseFields":[{"label":"1","question":"bate___ar / bate___em"},{"label":"2","question":"asse___ar / asse___em"},{"label":"3","question":"via___ar / via___ge"},{"label":"4","question":"bande___ar / bande___em"},{"label":"5","question":"allo___ar / allo___em"},{"label":"6","question":"colpe___ar / colpe___em"},{"label":"7","question":"pu___ar / pu___em"},{"label":"8","question":"avanta___ar / avanta___e"},{"label":"9","question":"assa___ar / assa___ista"},{"label":"10","question":"desi___ar / desi___e"},{"label":"11","question":"encora___ar / cora___e"},{"label":"12","question":"enve___ar / enve___em"},{"label":"13","question":"passe___ar / passe___em"},{"label":"14","question":"ultra___ar / ultra___e"},{"label":"15","question":"rebu___ar / rebu___em"},{"label":"16","question":"pu___ar / pu___em"},{"label":"17","question":"mare___ar / mare___em"},{"label":"18","question":"trosse___ar / trosse___em"},{"label":"19","question":"plante___ar / plante___em"},{"label":"20","question":"plu___a / plu___es"},{"label":"21","question":"xafarde___ar / xafarde___em"},{"label":"22","question":"cue___ar / cue___em"}],"solutionHtml":"<ul><li>batejar / bategem</li><li>assetjar / assetgem</li><li>viatjar / viatge</li><li>bandejar / bandegem</li><li>allotjar / allotgem</li><li>colpejar / colpegem</li><li>pujar / pugem</li><li>avantatjar / avantatge</li><li>assajar / assagista</li><li>desitjar / desitge (valencià)</li><li>encoratjar / coratge</li><li>envejar / envegem</li><li>passejar / passegem</li><li>ultratjar / ultratge</li><li>rebutjar / rebutgem</li><li>pujar / pugem</li><li>marejar / maregem</li><li>trossejar / trossegem</li><li>plantejar / plantegem</li><li>pluja / pluges</li><li>xafardejar / xafardegem</li><li>cuejar / cuegem</li></ul>"},{"id":"t9-ex4","number":"09.4","title":"Completa les frases","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Entre els ordes reli___iosos hi havia els dominics, els ___erònims i els ___esuïtes."},{"label":"2","question":"Més val que aneu pro___ectant la vostra ___ubilació."},{"label":"3","question":"Si el cap de setmana hi haurà o no plu___es són només con___ectures."},{"label":"4","question":"Tenia una tar___eta que li permetia via___ar en un ___et privat ma___estuós."},{"label":"5","question":"La tra___ectòria del pro___ectil estava amagada en un ___eroglífic."},{"label":"6","question":"Era tan ___elosa que, quan va descobrir que el còn___u___e flirte___ava amb altres, es va plante___ar ven___ar-se’n."},{"label":"7","question":"Els mi___ans de comunicació han aire___at les investigacions per a distin___ir entre l’ADN propi i aliè dels animals extin___its."}],"solutionHtml":"<ul><li>religiosos, jerònims, jesuïtes</li><li>projectant, jubilació</li><li>pluges, conjectures</li><li>targeta, viatjar, jet, majestuós</li><li>trajectòria, projectil, jeroglífic</li><li>gelosa, cònjuge, flirtejava, plantejar, venjar-se’n</li><li>mitjans, airejat, distingir, extingits</li></ul>"},{"id":"t9-ex5","number":"09.5","title":"Completa les grafies","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa amb j/g, gu/gü, x/tx/ig o tj/tg, segons el mot.</p>","responseFields":[{"label":"1","question":"___ermà"},{"label":"2","question":"pro___ecte"},{"label":"3","question":"___aqueta"},{"label":"4","question":"taron___a"},{"label":"5","question":"taron___es"},{"label":"6","question":"gran___a"},{"label":"7","question":"tar___eta"},{"label":"8","question":"despa___"},{"label":"9","question":"forma___e"},{"label":"10","question":"via___e"},{"label":"11","question":"___ec (de diners)"},{"label":"12","question":"___ec (d’un país)"},{"label":"13","question":"gui___"},{"label":"14","question":"___ocar"},{"label":"15","question":"esqui___"},{"label":"16","question":"esto___"},{"label":"17","question":"ma___ (mes)"},{"label":"18","question":"passe___"},{"label":"19","question":"fle___a"},{"label":"20","question":"___ocolate"}],"solutionHtml":"<ul><li>germà</li><li>projecte</li><li>jaqueta</li><li>taronja</li><li>taronges</li><li>granja</li><li>targeta</li><li>despatx</li><li>formatge</li><li>viatge</li><li>xec</li><li>txec</li><li>guix</li><li>xocar</li><li>esquitx</li><li>estoig</li><li>maig</li><li>passeig</li><li>fletxa</li><li>xocolate</li></ul>"},{"id":"t9-ex6","number":"09.6","title":"Present d’indicatiu","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Conjuga passejar: jo, tu, ell/ella."},{"label":"2","question":"Conjuga jutjar: jo, tu, ell/ella."}],"solutionHtml":"<ul><li>jo passejo (passege), tu passeges, ell/ella passeja.</li><li>jo jutjo (jutge), tu jutges, ell/ella jutja.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Per al so de j, escrivim habitualment j davant de a/o/u i g davant de e/i. Hi ha excepcions amb j davant de e: Jesús, jerarquia, jersei, projecte.</li><li>Els dígrafs tj/tg alternen segons la vocal: tj davant de a/o/u, tg davant de e/i.</li><li>Les famílies mantenen la grafia simple o el dígraf: passejar/passegem; jutjar/jutgem.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>ja, ge, gi, jo, ju</li><li>ga, gue, gui, go, gu</li><li>gua, güe, güi, guo</li><li>viatge / viatjar</li><li>metge / metgessa</li></ul></div></section>"},{"id":"t10","topicNumber":"10","title":"La lletra H","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t10-ex1","number":"10.1","title":"Completa el text amb H, si cal","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"___avui m’___e llevat molt d’___ora perquè volia anar a visitar l’___ivernacle que ___i ___a vora l’___ospital. Tot era ___armonia i jo ___em sentia ___alegre i de bon ___umor. Quan ___i ___e arribat encara era tancat ___i he decidit anar ___a prendre una ___orxata al bar de la cantonada. Només ___i ___avia dos ___omes en un racó que discutien en veu baixa. De sobte, ___an començat ___a cridar i ___a ___esbatussar-se ___i, sense adonar-me’n, m’___e convertit en l’únic testimoni d’un ___omicidi. M’___e posat ___a córrer com un co___et, però l’___assassí m’___a ___enxampat i ___ara sóc el seu ___ostatge."}],"solutionHtml":"<p>Avui m’he llevat molt d’hora perquè volia anar a visitar l’hivernacle que hi ha vora l’hospital. Tot era harmonia i jo em sentia alegre i de bon humor. Quan hi he arribat encara era tancat i he decidit anar a prendre una orxata al bar de la cantonada. Només hi havia dos homes en un racó que discutien en veu baixa. De sobte, han començat a cridar i a esbatussar-se i, sense adonar-me’n, m’he convertit en l’únic testimoni d’un homicidi. M’he posat a córrer com un coet, però l’assassí m’ha enxampat i ara sóc el seu ostatge.</p>"},{"id":"t10-ex2","number":"10.2","title":"H inicial, intercalada o sense H","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa amb h si cal i indica el número de la regla de la teoria: 1.a (mots amb h inicial), 1.e (prefixos) o 2 (h intercalada). Escriu «sense h» quan correspongui. Helena és un nom propi amb h inicial.</p>","responseFields":[{"label":"1","question":"___vui"},{"label":"2","question":"caca___uet"},{"label":"3","question":"___armonia"},{"label":"4","question":"___iperactiu"},{"label":"5","question":"___eterogeni"},{"label":"6","question":"___ou"},{"label":"7","question":"ad___esió"},{"label":"8","question":"sub___asta"},{"label":"9","question":"___elena"},{"label":"10","question":"___igiene"},{"label":"11","question":"___ivern"}],"solutionHtml":"<ul><li>avui: sense h</li><li>cacauet: sense h</li><li>harmonia: 1.a, h inicial</li><li>hiperactiu: 1.e, prefix hiper-</li><li>heterogeni: 1.e, prefix hetero-</li><li>ou: sense h</li><li>adhesió: 2, h intercalada</li><li>subhasta: 2, h intercalada</li><li>Helena: nom propi amb h</li><li>higiene: 1.a, h inicial</li><li>hivern: 1.a, h inicial</li></ul>"},{"id":"t10-ex3","number":"10.3","title":"Historieta amb H","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Tria almenys deu paraules de la teoria i escriu una història de cinc línies com a mínim."}],"solutionHtml":"<p>Pauta: comprova el nombre de mots i de línies; distingeix la h inicial, la intercalada i les formes d’haver. No afegeixis h a avui, orxata, coet ni ostatge.</p>"},{"id":"t10-ex4","number":"10.4","title":"A, AH o HA","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"___ sí? Vindràs ___ sopar? Doncs t’hi esperem ___ les nou!"},{"label":"2","question":"Ja ___ tornat ___ fer de les seues. No ___ canviat gens."},{"label":"3","question":"No ___ portat el diari ___ casa ni ___ anat ___ comprar el pa."}],"solutionHtml":"<ul><li>Ah; a; a</li><li>ha; a; ha</li><li>ha; a; ha; a</li></ul>"},{"id":"t10-ex5","number":"10.5","title":"EM, HEM, HE o EH","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"___ miro a l’espill i ___ rento les mans."},{"label":"2","question":"___, atura’t! No ___ vist el que passava i ___ pareix que ___ atropellat algú!"},{"label":"3","question":"___ agafat l’autobús i ___ arribat a l’hora."},{"label":"4","question":"Esperem que no ___ suspenguin i ___ pugui matricular a la universitat."}],"solutionHtml":"<ul><li>Em; em</li><li>Eh; he; em; he</li><li>He / Hem; he / hem (mantén la mateixa persona)</li><li>em; em</li></ul>"},{"id":"t10-ex6","number":"10.6","title":"O o HO","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Em portaràs a patinar ___ no ___ saps encara si podràs ___ no?"},{"label":"2","question":"___ va dir tan baixet que no ___ vaig sentir."},{"label":"3","question":"Com t’agrada l’amanida, amb vinagre ___ sense?"},{"label":"4","question":"El que t’he dit no ___ diguis a ma germana."},{"label":"5","question":"No ___ sé."}],"solutionHtml":"<ul><li>o; ho; o</li><li>Ho; ho</li><li>o</li><li>ho</li><li>ho</li></ul>"},{"id":"t10-ex7","number":"10.7","title":"I o HI","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Vés al forn ___ compra’m un xusco de pa."},{"label":"2","question":"___ ha molta gent com tu."},{"label":"3","question":"Demà no ___ vaig. Avisa l’escola ___ el bus."},{"label":"4","question":"Quan vaig arribar al cine, ell ja ___ estava."}],"solutionHtml":"<ul><li>i</li><li>Hi</li><li>hi; i</li><li>hi</li></ul>"},{"id":"t10-ex8","number":"10.8","title":"Frases per distingir les formes","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Escriu cinc frases utilitzant els casos anteriors: a/ah/ha, em/hem/he/eh, o/ho i i/hi."}],"solutionHtml":"<ul><li>Ah, la Maria ha anat a casa.</li><li>Em sembla que hem arribat aviat.</li><li>Eh, jo ja he acabat!</li><li>Ho vols amb sucre o sense?</li><li>Hi anirem tu i jo.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>La hac habitualment és muda. Cal conservar-la en mots com home, hivern, harmonia i en les formes del verb haver.</li><li>Els pronoms hi i ho porten h. Algunes paraules tenen h intercalada.</li><li>Alguns manlleus tenen h aspirada: no s’hi apostrofa davant si la h es pronuncia.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>he, ha, hem, havia</li><li>hi ha; no ho sé</li><li>ahir, vehicle, subhasta, cohesió</li><li>ah!, eh!, oh!</li><li>de Houston</li></ul></div></section>"},{"id":"t11","topicNumber":"11","title":"La S sorda i la S sonora","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t11-ex1","number":"11.1","title":"Completa la descripció dels sons","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Amb quin so compares la s sonora? Quines grafies té? Posa un exemple."},{"label":"2","question":"Amb quin so compares la s sorda? Quines grafies té? Posa un exemple."}],"solutionHtml":"<ul><li>La s sonora pot comparar-se amb el brunzit d’un insecte. Grafies principals: s i z. Exemple: casa.</li><li>La s sorda pot comparar-se amb un xiuxiueig. Grafies: s, ss, c i ç. Exemple: sal.</li></ul>"},{"id":"t11-ex2","number":"11.2","title":"Classificació segons la posició","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"A principi de paraula: grafies i cinc exemples de cada so."},{"label":"2","question":"Entre vocals: grafies i cinc exemples de cada so."},{"label":"3","question":"Abans o després de consonant: grafies i quatre exemples de cada so."},{"label":"4","question":"A final de paraula: grafies i dos exemples de s sorda. Explica què passa amb la sonoritat."}],"solutionHtml":"<ul><li>Sonora: zero, zona, zebra, zoo, zodíac. Sorda: sal, sol, sac, cel, cirera.</li><li>Sonora: casa, cosa, rosa, camisa, música. Sorda: tassa, passar, peça, caça, oceà.</li><li>Sonora: colze, onze, dotze, quinze, pinzell. Sorda: pensar, dansa, cansat, força, cançó.</li><li>En pronunciació aïllada, el so final és sord: arròs, pas, braç, feliç.</li></ul>"},{"id":"t11-ex3","number":"11.3","title":"Completa i indica si el so és sord o sonor","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa amb s, ss, c, ç o z. Al quadern es demana subratllar cada so amb un color diferent: a la web, indica al costat de cada grafia si és sorda o sonora.</p>","responseFields":[{"label":"1","question":"profe___or"},{"label":"2","question":"can___ó"},{"label":"3","question":"esperan___a"},{"label":"4","question":"co___a"},{"label":"5","question":"ca___a (viure)"},{"label":"6","question":"___iment"},{"label":"7","question":"ca___a (animals)"},{"label":"8","question":"col___e"},{"label":"9","question":"cerve___a"},{"label":"10","question":"ta___a"},{"label":"11","question":"Sarago___a"},{"label":"12","question":"con___tàn___ia"},{"label":"13","question":"arrò___"},{"label":"14","question":"bra___"},{"label":"15","question":"Parí___"},{"label":"16","question":"ba___"},{"label":"17","question":"a___o___ia___ió"},{"label":"18","question":"bo___a"},{"label":"19","question":"for___a"},{"label":"20","question":"en___iam"},{"label":"21","question":"ne___e___itat"},{"label":"22","question":"___ero"},{"label":"23","question":"___oo"},{"label":"24","question":"___irera"},{"label":"25","question":"___abata"},{"label":"26","question":"___èrvol"},{"label":"27","question":"___ebra"},{"label":"28","question":"___el"},{"label":"29","question":"___agala"},{"label":"30","question":"for___a"}],"solutionHtml":"<ul><li>professor: sorda</li><li>cançó: sorda</li><li>esperança: sorda</li><li>cosa: sonora</li><li>casa: sonora</li><li>ciment: sorda</li><li>caça: sorda</li><li>colze: sonora</li><li>cervesa: sorda inicial i sonora intervocàlica</li><li>tassa: sorda</li><li>Saragossa: sorda</li><li>constància: sorda</li><li>arròs: sorda</li><li>braç: sorda</li><li>París: sorda final</li><li>baç: sorda</li><li>associació: sordes</li><li>bossa: sorda</li><li>força: sorda</li><li>enciam: sorda</li><li>necessitat: sordes</li><li>zero: sonora</li><li>zoo: sonora</li><li>cirera: sorda</li><li>sabata: sorda</li><li>cérvol: sorda</li><li>zebra: sonora</li><li>cel: sorda; zel: sonora (segons el significat)</li><li>zagala: sonora</li><li>força: sorda</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>La s sonora fa vibrar les cordes vocals; la s sorda no.</li><li>La s sonora s’escriu principalment s entre vocals i z a principi de mot o en altres posicions.</li><li>La s sorda pot escriure’s s, ss, c o ç. C davant de e/i; ç davant de a/o/u o a final de mot.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>casa / caça</li><li>rosa / rossa</li><li>zero, colze</li><li>sal, passar, cel, braç</li></ul></div></section>"},{"id":"t12","topicNumber":"12","title":"Els pronoms febles","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t12-ex1","number":"12.1","title":"Pronoms i funció sintàctica","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa amb el pronom feble i indica la funció sintàctica del complement que substitueix. Els elements de referència, que el quadern marca amb subratllat, són:</p><ol><li>un regal</li><li>la persona que es renta les mans</li><li>la Marta</li><li>al Miquel (i, si escau, el llibre)</li><li>taronges</li><li>a Beseit</li><li>de Beseit</li><li>això</li><li>els seus amics</li><li>a les alumnes</li></ol>","responseFields":[{"label":"1","question":"Miquel compra un regal; si no li agrada, ___ comprarà un altre."},{"label":"2","question":"Marta es menja una taronja; quan acabi, ___ rentarà les mans."},{"label":"3","question":"Anna tatua la Marta; quan acabi de tatuar___ ens ho ensenyarà."},{"label":"4","question":"Tamara regala un llibre al Miquel i ___ donarà demà."},{"label":"5","question":"Marta compra taronges al súper. Marta ___ compra tots els dies."},{"label":"6","question":"Miquel va a Beseit cada dia. Els dilluns ___ va amb cotxe."},{"label":"7","question":"Miquel torna de Beseit. Els dimarts ___ torna a peu."},{"label":"8","question":"Agafa això. Agafa___."},{"label":"9","question":"Josep ha quedat amb els seus amics i ___ veurà demà."},{"label":"10","question":"Anna porta unes cadires a les alumnes i després ___ portarà un coixí."}],"solutionHtml":"<ul><li>en: CD indefinit (un regal).</li><li>es: CI reflexiu; les mans és el CD.</li><li>-la: CD (la Marta).</li><li>li: CI (al Miquel), si substituïm només el destinatari. Si substituïm també el llibre: l’hi donarà / li’l donarà.</li><li>en: CD (taronges).</li><li>hi: complement de lloc.</li><li>en: complement de lloc d’origen.</li><li>agafa-ho: CD neutre.</li><li>els: CD (els seus amics).</li><li>els: CI (a les alumnes).</li></ul>"},{"id":"t12-ex2","number":"12.2","title":"Formes dels pronoms personals febles","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"","responseFields":[{"label":"1","question":"Maria ___ (a mi) renta."},{"label":"2","question":"Miquel ___ (a tu) mira."},{"label":"3","question":"Clara ___ aixeca del llit."},{"label":"4","question":"Vosaltres sempre ___ vestiu ràpid."},{"label":"5","question":"El professor ___ reparteix l’examen (a nosaltres)."},{"label":"6","question":"Agafa___ la mà (a mi)."},{"label":"7","question":"Carla ___ beu la llet."},{"label":"8","question":"Cal menjar___ tot l’esmorzar."}],"solutionHtml":"<ul><li>em</li><li>et</li><li>s’</li><li>us</li><li>ens</li><li>’m: agafa’m</li><li>es</li><li>se: menjar-se</li></ul>"},{"id":"t12-ex3","number":"12.3","title":"Deu expressions amb pronoms febles","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Inventa deu expressions amb un company o companya. Indica el pronom i què substitueix."}],"solutionHtml":"<ul><li>Em rento; et miro; s’aixeca; ens vestim; us escolto; el compro; la veig; en vull dos; ho sé; hi vaig.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Els pronoms eviten repetir complements. Habitualment precedeixen el verb; amb infinitiu, gerundi i imperatiu afirmatiu van darrere.</li><li>CD determinat: el, la, els, les. CD indefinit o quantificat: en. CD neutre: ho.</li><li>CI: li en singular i els en plural. Complement de lloc: hi; origen introduït per de: en.</li><li>No tots els pronoms s’apostrofen: cal aplicar la forma adequada a cada context.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>El compra / l’agafa / compra’l</li><li>En vull dues.</li><li>Ho explicaré.</li><li>Li dono el llibre.</li><li>Hi vaig / en torno.</li></ul></div></section>"},{"id":"t13","topicNumber":"13","title":"R, RR i R muda","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t13-ex1","number":"13.1","title":"Completa amb R o RR","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa els mots i indica les r que són mudes en la teva varietat de català.</p>","responseFields":[{"label":"1","question":"Cada dia en a___iba___ a classe, t___eia la ca___peta i un pape___ i es p___epa___ava per comença___"},{"label":"2","question":"Avui el p___ofesso___ estava molt encantado___ i els havia ___egalat un punt i una ___osa; feia ca___a de vole___ canta___"},{"label":"3","question":"Per la finest___a veia la blanco___ dels ametlle___s en el p___océs de flori___"},{"label":"4","question":"Es va fe__ un auto__etrat poc __ealista"},{"label":"5","question":"Hem fet posa__ una __eixa de fe__o al balcó"},{"label":"6","question":"En Ricard i la Cla__a fan su__ar vaixells de pape__ damunt l'aigua"},{"label":"7","question":"Voldria sabe__ per què tothom co__e pel ca__er"},{"label":"8","question":"La blavo__ del mar em produeix enyo__"},{"label":"9","question":"Se sentia a la sala un xiva__i infe__nal"},{"label":"10","question":"De tant p__endre el sol, t'ha quedat la pell ben to__ada"},{"label":"11","question":"Ha a__ibat un ca__egament d'a__òs"},{"label":"12","question":"El record se li havia esbo__at de la memòria"},{"label":"13","question":"Les rodes de la ca__ossa són de fe__o"},{"label":"14","question":"El van inte__ogar d'una manera totalment __acional."}],"solutionHtml":"<ul><li>Cada dia, en arribar a classe, treia la carpeta i un paper i es preparava per començar.</li><li>Avui el professor estava molt encantador i els havia regalat un punt i una rosa; feia cara de voler cantar.</li><li>Per la finestra veia la blancor dels ametllers en el procés de florir.</li><li>Es va fer un autoretrat poc realista.</li><li>Hem fet posar una reixa de ferro al balcó.</li><li>En Ricard i la Clara fan surar vaixells de paper damunt l’aigua.</li><li>Voldria saber per què tothom corre pel carrer.</li><li>La blavor del mar em produeix enyor.</li><li>Se sentia a la sala un xivarri infernal.</li><li>De tant prendre el sol, t’ha quedat la pell ben torrada.</li><li>Ha arribat un carregament d’arròs.</li><li>El record se li havia esborrat de la memòria.</li><li>Les rodes de la carrossa són de ferro.</li><li>El van interrogar d’una manera totalment racional.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>La r simple apareix en cara; la r múltiple, en rosa i carro. Entre vocals, la r múltiple sol escriure’s rr.</li><li>A principi de mot i en molts compostos s’escriu r: rosa, autoretrat.</li><li>En moltes varietats, la r final no es pronuncia en infinitius i en altres mots, però es manté escrita. La pronunciació varia segons el dialecte.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>cara / carro</li><li>enraonar</li><li>autoretrat</li><li>cantar, fuster, paper</li></ul></div></section>"},{"id":"t14","topicNumber":"14","title":"L’ela geminada","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t14-ex1","number":"14.1","title":"Classifica les paraules amb L·L","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<div class=\"grammar-bank\"><h4>Banc de paraules</h4><ul><li>al·lèrgia</li><li>goril·la</li><li>oscil·lar</li><li>vacil·lar</li><li>aquarel·la</li><li>novel·la</li><li>col·loqui</li><li>varicel·la</li><li>síl·laba</li><li>parcel·la</li><li>mortadel·la</li><li>clorofil·la</li><li>cavil·lar</li><li>tranquil·la</li><li>mil·límetre</li><li>al·lusió</li><li>sil·logisme</li><li>col·lapse</li><li>col·laborar</li><li>til·la</li><li>destil·lar</li><li>il·legal</li><li>al·licient</li><li>miler</li><li>col·legi</li><li>il·lès</li><li>franel·la</li><li>mil·lèsima</li><li>col·lecció</li><li>al·lucinar</li><li>col·lega</li><li>al·ludir</li><li>il·lusió</li><li>col·locar</li><li>milió</li><li>pel·lícula</li><li>il·luminar</li><li>al·lot</li><li>sol·licitar</li><li>mil·lenari</li></ul></div>","responseFields":[{"label":"1","question":"al·l-"},{"label":"2","question":"col·l-"},{"label":"3","question":"il·l-"},{"label":"4","question":"mil·l-"},{"label":"5","question":"Excepcions amb mil-"},{"label":"6","question":"sil·l-"},{"label":"7","question":"-el·la"},{"label":"8","question":"-il·la"},{"label":"9","question":"-il·lar"},{"label":"10","question":"Altres paraules"}],"solutionHtml":"<ul><li>al·lèrgia, al·lusió, al·licient, al·lucinar, al·ludir, al·lot.</li><li>col·loqui, col·lapse, col·laborar, col·legi, col·lecció, col·lega, col·locar.</li><li>il·legal, il·lès, il·lusió, il·luminar.</li><li>mil·límetre, mil·lèsima, mil·lenari.</li><li>miler, milió.</li><li>síl·laba, sil·logisme.</li><li>aquarel·la, novel·la, varicel·la, parcel·la, mortadel·la, franel·la.</li><li>goril·la, clorofil·la, tranquil·la, til·la.</li><li>oscil·lar, vacil·lar, cavil·lar, destil·lar.</li><li>pel·lícula, sol·licitar.</li></ul>"},{"id":"t14-ex2","number":"14.2","title":"Busca exemples al llibre","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Anota dues paraules amb l·l i la pàgina del llibre on les has trobades."}],"solutionHtml":"<p>Pauta: escriu dos mots reals amb punt volat i comprova les pàgines en el llibre que estiguis llegint.</p>"},{"id":"t14-ex3","number":"14.3","title":"Consulta el diccionari","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Tria quatre mots amb l·l que no coneguis i escriu-ne el significat."}],"solutionHtml":"<p>Pauta: indica el mot, el significat que has consultat i una frase que n’il·lustri l’ús.</p>"},{"id":"t14-ex4","number":"14.4","title":"Historieta amb L·L","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Escriu una història de quatre línies com a mínim amb vuit paraules amb l·l."}],"solutionHtml":"<p>Pauta: compta vuit mots amb l·l, utilitza el punt volat i comprova que la història tingui sentit.</p>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>L’ela geminada s’escriu l·l, amb un punt volat. Es distingeix del dígraf ll.</li><li>Molts mots comencen per al·l-, col·l-, il·l-, mil·l- o sil·l-. Cal aprendre’n les excepcions.</li><li>Són freqüents les terminacions -el·la, -il·la i -il·lar. La pronunciació pot variar segons el parlant.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>col·legi</li><li>il·lusió</li><li>novel·la</li><li>tranquil·la</li><li>milió i miler: sense punt volat</li></ul></div></section>"},{"id":"t15","topicNumber":"15","title":"Els verbs","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t15-ex1","number":"15.1","title":"Les conjugacions","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Dos verbs acabats en -ar."},{"label":"2","question":"Dos verbs acabats en -er."},{"label":"3","question":"Dos verbs acabats en -re."},{"label":"4","question":"Dos verbs purs de la tercera conjugació."},{"label":"5","question":"Dos verbs incoatius de la tercera conjugació."}],"solutionHtml":"<ul><li>cantar, ballar.</li><li>témer, vèncer.</li><li>beure, perdre.</li><li>dormir, sortir.</li><li>servir, patir.</li></ul>"},{"id":"t15-ex2","number":"15.2","title":"Infinitius i gerundis","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Busca dos infinitius al llibre i fes una frase amb cadascun."},{"label":"2","question":"Busca dos gerundis al llibre i fes una frase amb cadascun."}],"solutionHtml":"<ul><li>Model: cantar → M’agrada cantar; llegir → Vull llegir.</li><li>Model: cantant → Estic cantant; llegint → Estava llegint.</li></ul>"},{"id":"t15-ex3","number":"15.3","title":"L’imperfet amb V","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Tria dos verbs en -ar i conjuga’ls en imperfet en totes les persones."}],"solutionHtml":"<ul><li>Model, ballar: ballava, ballaves, ballava, ballàvem, ballàveu, ballaven.</li><li>Model, mirar: mirava, miraves, mirava, miràvem, miràveu, miraven.</li></ul>"},{"id":"t15-ex4","number":"15.4","title":"Vocals de les terminacions verbals","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Tria dos verbs i escriu-ne la tercera persona singular de l’imperfet."},{"label":"2","question":"Tria dos verbs i escriu-ne la tercera persona singular del plusquamperfet."},{"label":"3","question":"Tria dos verbs i escriu-ne la primera i la tercera persona singular del condicional."}],"solutionHtml":"<ul><li>ell mirava; ell cantava.</li><li>ell havia mirat; ell havia cantat.</li><li>jo/ell miraria; jo/ell cantaria.</li></ul>"},{"id":"t15-ex5","number":"15.5","title":"El plusquamperfet","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Tria dos verbs i conjuga’ls amb haver en totes les persones."}],"solutionHtml":"<ul><li>Model: havia begut, havies begut, havia begut, havíem begut, havíeu begut, havien begut.</li><li>Model: havia llegit, havies llegit, havia llegit, havíem llegit, havíeu llegit, havien llegit.</li></ul>"},{"id":"t15-ex6","number":"15.6","title":"Dues formes de passat","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Tria un verb i conjuga’l en passat simple."},{"label":"2","question":"Conjuga el mateix verb en passat perifràstic."}],"solutionHtml":"<ul><li>Model: cantí, cantares, cantà, cantàrem, cantàreu, cantaren.</li><li>Model: vaig cantar, vas cantar, va cantar, vam cantar, vau cantar, van cantar.</li></ul>"},{"id":"t15-ex7","number":"15.7","title":"Completa les conjugacions","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>El quadre del quadern barreja menjava amb menjaríem. Aquí es presenta el condicional de manera coherent.</p>","responseFields":[{"label":"1","question":"Condicional de cantar: jo cantaria, tu…, ell…, nosaltres…, vosaltres…, ells…"},{"label":"2","question":"Condicional de menjar: jo menjaria, tu…, ell…, nosaltres…, vosaltres…, ells…"},{"label":"3","question":"Imperfet d’haver: jo havia, tu…, ell…, nosaltres…, vosaltres…, ells…"},{"label":"4","question":"Imperfet de dormir: jo dormia, tu…, ell…, nosaltres…, vosaltres…, ells…"}],"solutionHtml":"<ul><li>cantaria, cantaries, cantaria, cantaríem, cantaríeu, cantarien.</li><li>menjaria, menjaries, menjaria, menjaríem, menjaríeu, menjarien.</li><li>havia, havies, havia, havíem, havíeu, havien.</li><li>dormia, dormies, dormia, dormíem, dormíeu, dormien.</li></ul>"},{"id":"t15-ex8","number":"15.8","title":"Dictat sobre els verbs","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Escriu el dictat que et llegeixi la professora o un company."}],"solutionHtml":"<p>El PDF només inclou el títol d’aquesta activitat; no conté el text ni l’àudio del dictat. Revisa el resultat amb la persona que l’hagi llegit.</p>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Hi ha tres conjugacions: -ar; -er/-re; -ir. En la tercera hi ha verbs purs i incoatius.</li><li>L’imperfet de la primera conjugació s’escriu amb v: cantava. Els temps compostos es formen amb haver i un participi.</li><li>El passat simple i el passat perifràstic expressen accions passades acabades. El seu ús varia segons la varietat i el registre.</li><li>Les formes planes acabades en -ia no duen accent, però les formes com cantaríem o dormíeu sí que en duen.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>cantar, témer, beure, dormir, servir</li><li>havia begut</li><li>ballí / vaig ballar</li><li>cantaria / cantaríem</li></ul></div></section>"},{"id":"t16","topicNumber":"16","title":"El gènere del substantiu: masculí i femení","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t16-ex1","number":"16.1","title":"Classifica els substantius","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<div class=\"grammar-bank\"><h4>Banc de paraules</h4><ul><li>senyor-senyora</li><li>avi-àvia</li><li>oncle-tia</li><li>ciclista</li><li>gimnasta</li><li>jove</li><li>conserge</li><li>actor-actriu</li><li>merla-merlot</li><li>amic-amiga</li><li>pianista</li><li>parricida</li><li>psicòleg-psicòloga</li><li>gall-gallina</li><li>alumne-alumna</li><li>monjo-monja</li><li>porc-truja</li><li>boc-cabra</li><li>cavall-egua</li><li>abella-abellot</li><li>boletaire</li><li>telefonista</li><li>trapezista</li><li>gos-gossa</li><li>bruixa-bruixot</li><li>llop-lloba</li><li>marit-muller</li><li>jueu-jueva</li><li>nebot-neboda</li><li>home-dona</li><li>cosí-cosina</li><li>bou-vaca</li><li>mascle-femella</li><li>perdiu-perdigot</li><li>fill-filla</li><li>net-neta</li><li>metge-metgessa</li><li>hereu-hereva</li><li>abat-abadessa</li><li>emperador-emperadriu</li><li>duc-duquessa</li><li>noi-noia</li><li>mestre-mestra</li><li>professor-professora</li><li>amo-mestressa</li></ul></div>","responseFields":[{"label":"1","question":"Afegim -a sense altres canvis."},{"label":"2","question":"Afegim -a amb canvis ortogràfics."},{"label":"3","question":"Canvi de vocal final per -a."},{"label":"4","question":"Terminacions -na, -ina o -essa."},{"label":"5","question":"Terminacions -or/-riu o -òleg/-òloga."},{"label":"6","question":"Masculí amb -ot."},{"label":"7","question":"Arrels diferents o altres formes irregulars."},{"label":"8","question":"Invariables en -aire, -ista, -cida, -ta."},{"label":"9","question":"Altres invariables."}],"solutionHtml":"<ul><li>senyor-senyora, avi-àvia, fill-filla, net-neta, noi-noia, professor-professora.</li><li>amic-amiga, gos-gossa, llop-lloba, jueu-jueva, nebot-neboda, hereu-hereva.</li><li>alumne-alumna, monjo-monja, mestre-mestra.</li><li>cosí-cosina, gall-gallina, metge-metgessa, abat-abadessa, duc-duquessa.</li><li>actor-actriu, emperador-emperadriu, psicòleg-psicòloga.</li><li>merla-merlot, abella-abellot, bruixa-bruixot, perdiu-perdigot.</li><li>oncle-tia, porc-truja, boc-cabra, cavall-egua, marit-muller, home-dona, bou-vaca, mascle-femella, amo-mestressa.</li><li>ciclista, gimnasta, pianista, parricida, boletaire, telefonista, trapezista.</li><li>jove, conserge.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>El femení sovint es forma afegint -a, amb possibles canvis ortogràfics.</li><li>Alguns mots canvien la vocal final o afegeixen terminacions com -na, -ina o -essa.</li><li>Hi ha parelles d’arrels diferents i noms invariables. En alguns noms d’animals, el masculí es forma amb -ot.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>amic / amiga</li><li>nebot / neboda</li><li>alumne / alumna</li><li>cosí / cosina</li><li>actor / actriu</li><li>home / dona</li><li>el / la ciclista</li><li>abella / abellot</li></ul></div></section>"},{"id":"t17","topicNumber":"17","title":"X, TX i IG","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t17-ex1","number":"17.1","title":"Regles i exemples","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"X a principi de paraula: sis exemples."},{"label":"2","question":"TX inicial: quatre topònims o gentilicis."},{"label":"3","question":"TX entre vocals: sis exemples."},{"label":"4","question":"X després de consonant: quatre exemples."},{"label":"5","question":"TX a final de paraula: cinc exemples."}],"solutionHtml":"<ul><li>xoc, xiquet, xec, xut, xalar, xocolate.</li><li>Txèquia, txec, Txad, txadià.</li><li>motxilla, batxillerat, pitxer, cotxe, escabetxar, capritxós.</li><li>anxova, perxa, conxa, ponx.</li><li>cartutx, despatx, capritx, matx, empatx.</li></ul>"},{"id":"t17-ex2","number":"17.2","title":"Classifica les paraules","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<div class=\"grammar-bank\"><h4>Banc de paraules</h4><ul><li>cartutx</li><li>motxilla</li><li>despatx</li><li>batxillerat</li><li>xocolate</li><li>anxova</li><li>pitxer</li><li>xalar</li><li>Txèquia</li><li>escabetxar</li><li>perxa</li><li>capritx</li><li>Txad</li><li>matx</li><li>conxa</li><li>capritxós</li><li>ponx</li><li>txadià</li><li>txec</li><li>empatx</li><li>xoc</li><li>xiquet</li><li>xec</li><li>cotxe</li><li>xut</li></ul></div>","responseFields":[{"label":"1","question":"X inicial"},{"label":"2","question":"TX inicial"},{"label":"3","question":"TX entre vocals"},{"label":"4","question":"X després de consonant"},{"label":"5","question":"TX final"}],"solutionHtml":"<ul><li>xocolate, xalar, xoc, xiquet, xec, xut.</li><li>Txèquia, Txad, txadià, txec.</li><li>motxilla, batxillerat, pitxer, escabetxar, capritxós, cotxe.</li><li>anxova, perxa, conxa, ponx.</li><li>cartutx, despatx, capritx, matx, empatx.</li></ul>"},{"id":"t17-ex3","number":"17.3","title":"Derivats i paraules primitives","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Completa i escriu la paraula primitiva acabada en -tx o -ig.</p>","responseFields":[{"label":"1","question":"rebu___ar"},{"label":"2","question":"empa___ós"},{"label":"3","question":"esqui___ar"},{"label":"4","question":"ro___or"},{"label":"5","question":"passe___ar"},{"label":"6","question":"capri___ós"}],"solutionHtml":"<ul><li>rebutjar → rebuig</li><li>empatxós → empatx</li><li>esquitxar → esquitx</li><li>rojor → roig</li><li>passejar → passeig</li><li>capritxós → capritx</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>El so africat de xec pot representar-se amb x, tx o ig. La pronunciació de la x inicial varia segons la varietat.</li><li>TX apareix entre vocals en mots com cotxe. A final de mot, distingim tx/ig observant els derivats.</li><li>Alguns noms d’origen estranger comencen per tx.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>xec, xiquet</li><li>cotxe, motxilla</li><li>cartutx → cartutxera</li><li>assaig → assajar</li><li>Txèquia → txec</li></ul></div></section>"},{"id":"t18","topicNumber":"18","title":"El nombre: singular i plural","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t18-ex1","number":"18.1","title":"Busca exemples de cada tipus de plural","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"<p>Busca exemples al llibre i escriu el singular i el plural. Les solucions són exemples possibles.</p>","responseFields":[{"label":"1","question":"Singular + s"},{"label":"2","question":"Vocal tònica + ns"},{"label":"3","question":"Plural en -os"},{"label":"4","question":"Plural amb -ssos"},{"label":"5","question":"-a → -es"},{"label":"6","question":"-ca → -ques"},{"label":"7","question":"-ça → -ces"},{"label":"8","question":"-ja → -ges"},{"label":"9","question":"-ga → -gues"},{"label":"10","question":"-gua → -gües"},{"label":"11","question":"Masculins en -sc/-st amb dues formes"},{"label":"12","question":"Noms invariables"}],"solutionHtml":"<ul><li>llibre / llibres.</li><li>camí / camins.</li><li>braç / braços.</li><li>gos / gossos.</li><li>casa / cases.</li><li>roca / roques.</li><li>plaça / places.</li><li>taronja / taronges.</li><li>amiga / amigues.</li><li>aigua / aigües.</li><li>bosc / boscs o boscos; gust / gusts o gustos.</li><li>llapis / llapis; dilluns / dilluns.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>El plural habitual afegeix -s. Molts mots acabats en vocal tònica afegeixen -ns, però hi ha excepcions.</li><li>Els mots acabats en a àtona solen fer el plural en -es, amb canvis ortogràfics si cal.</li><li>Alguns masculins afegeixen -os; alguns admeten dues formes. Hi ha noms invariables.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>xiquet / xiquets</li><li>torró / torrons</li><li>calaix / calaixos</li><li>pas / passos</li><li>vaca / vaques</li><li>llengua / llengües</li><li>disc / discs o discos</li><li>dilluns / dilluns; dissabte / dissabtes</li></ul></div></section>"},{"id":"t19","topicNumber":"19","title":"El so /k/: C, QU, QÜ, G i K","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t19-ex1","number":"19.1","title":"Sèries de síl·labes i exemples","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<p>Es corregeix la barreja de güe amb la sèrie de /k/ del quadre original.</p>","responseFields":[{"label":"1","question":"Completa la sèrie del so /s/: sa, se/ce, ___, ___, ___."},{"label":"2","question":"Completa la sèrie /k/: ca, ___, qui, ___, ___."},{"label":"3","question":"Completa la sèrie /k/ amb u pronunciada: ___, qüe, ___, quo."}],"solutionHtml":"<ul><li>sa, se/ce, si/ci, so/ço, su/çu: sal, cel, cim, sol, suc.</li><li>ca, que, qui, co, cu: casa, queixa, qui, colom, curt.</li><li>qua, qüe, qüi, quo: quatre, qüestió, ubiqüitat, quota.</li></ul>"},{"id":"t19-ex2","number":"19.2","title":"Regles i exemples","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"C davant de vocal: completa les vocals i posa sis exemples."},{"label":"2","question":"QU davant de vocal amb u muda: completa les vocals i posa sis exemples."},{"label":"3","question":"QU amb u pronunciada: vocals i sis exemples."},{"label":"4","question":"QÜ: vocals i quatre exemples."},{"label":"5","question":"C davant de consonant: quatre exemples."},{"label":"6","question":"G davant de consonant: tres exemples."},{"label":"7","question":"C final: quatre exemples."},{"label":"8","question":"G final: quatre exemples."},{"label":"9","question":"K: quatre exemples entre mots i símbols."}],"solutionHtml":"<ul><li>a, o, u: casa, cara, colom, cosa, curt, cultura.</li><li>e, i: que, paquet, enquesta, qui, màquina, enquitranar.</li><li>a, o: quatre, quant, quan, quadre, quota, quotidià.</li><li>e, i: qüestió, freqüència, conseqüència, ubiqüitat.</li><li>acció, actriu, accés, cactus.</li><li>suggerir, amígdala, fragment; també magnitud.</li><li>batec, pessic, amic, sec.</li><li>fang, sang, llarg, cartílag.</li><li>kurd, kiwi, kg, km.</li></ul>"},{"id":"t19-ex3","number":"19.3","title":"Classifica segons la grafia","type":"open","book":true,"quadern":true,"solutionKind":"quadern","bodyHtml":"<div class=\"grammar-bank\"><h4>Banc de paraules</h4><ul><li>fang</li><li>kg</li><li>colom</li><li>sang</li><li>qui</li><li>curt</li><li>actriu</li><li>cartílag</li><li>acció</li><li>kurd</li><li>qüestió</li><li>quotidià</li><li>suggerir</li><li>ubiqüitat</li><li>quant</li><li>cua</li><li>quatre</li><li>cosa</li><li>paquet</li><li>enquitranar</li><li>amígdala</li><li>quota</li><li>cara</li><li>quadre</li><li>quan</li><li>que</li><li>llarg</li><li>km</li><li>Nova York</li><li>màquina</li><li>conseqüència</li><li>fragment</li><li>batec</li><li>cactus</li><li>freqüència</li><li>magnitud</li><li>casa</li><li>accés</li><li>enquesta</li><li>pessic</li></ul></div>","responseFields":[{"label":"1","question":"C davant de vocal"},{"label":"2","question":"QU amb u muda"},{"label":"3","question":"QU amb u pronunciada"},{"label":"4","question":"QÜ"},{"label":"5","question":"C davant de consonant"},{"label":"6","question":"G davant de consonant"},{"label":"7","question":"C final"},{"label":"8","question":"G final"},{"label":"9","question":"K"}],"solutionHtml":"<ul><li>colom, curt, cua, cosa, cara, casa.</li><li>qui, paquet, enquitranar, que, màquina, enquesta.</li><li>quotidià, quant, quatre, quota, quadre, quan.</li><li>qüestió, ubiqüitat, conseqüència, freqüència.</li><li>actriu, acció, cactus, accés.</li><li>suggerir, amígdala, fragment, magnitud.</li><li>batec, pessic.</li><li>fang, sang, llarg, cartílag.</li><li>kg, kurd, km, Nova York.</li></ul>"},{"id":"t19-ex4","number":"19.4","title":"Història amb les grafies estudiades","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Escriu una història de cinc línies com a mínim amb dotze paraules que continguin les grafies estudiades."}],"solutionHtml":"<p>Pauta: identifica dotze mots, revisa c/qu/qü/g/k i comprova que la narració tingui coherència.</p>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Per representar /k/, escrivim c davant de a/o/u i qu davant de e/i.</li><li>Si la u es pronuncia, escrivim qua/quo i qüe/qüi. En cua no hi ha diftong i escrivim c.</li><li>C i g poden alternar en posició final segons la família: amic/amiga, llarg/llarga. No n’hi ha prou amb mirar si el mot és agut.</li><li>K apareix en manlleus, noms propis i símbols. Els símbols kg i km s’escriuen en minúscula.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>ca, que, qui, co, cu</li><li>qua, qüe, qüi, quo</li><li>cua / quatre</li><li>actriu, acció, cactus</li><li>suggerir, amígdala, fragment, magnitud</li><li>batec / bategar</li><li>kurd; kg; km</li></ul></div></section>"},{"id":"t20","topicNumber":"20","title":"La T muda","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t20-ex1","number":"20.1","title":"La T dels gerundis","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Quina forma verbal apareix a «estic cantant» i «estava ballant»?"},{"label":"2","question":"Busca cinc exemples al llibre i copia el fragment de frase."}],"solutionHtml":"<ul><li>Gerundi.</li><li>Exemples possibles: estava cantant; continua ballant; està menjant; va caminant; segueix llegint. Cal localitzar els teus exemples en el llibre.</li></ul>"},{"id":"t20-ex2","number":"20.2","title":"Famílies de mots i T final","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Quines dues consonants solen precedir la t final muda en els casos estudiats?"},{"label":"2","question":"Busca cinc mots al llibre i afegeix un derivat o una forma de la mateixa família."},{"label":"3","question":"Per què malalt porta t i mall no en porta?"}],"solutionHtml":"<ul><li>n i l.</li><li>Exemples: malalt/malalta, alt/alta, molt/molta, pont/pontet, sant/santa.</li><li>Malalt conserva la t de la família malalta, malaltia. Mall és una altra paraula, amb ll, i no té aquesta t.</li></ul>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>En moltes varietats, la t no es pronuncia en alguns grups finals com -nt i -lt, però es conserva en l’escriptura.</li><li>El gerundi acaba en -ant, -ent o -int. No és un temps personal, sinó una forma no personal del verb.</li><li>Els mots de la mateixa família ajuden a justificar les consonants escrites. La pronunciació varia segons el dialecte.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>cantant, ballant, llegint</li><li>malalt → malalta</li><li>pont → pontet</li><li>alt → alta</li></ul></div></section>"},{"id":"t21","topicNumber":"21","title":"Errades més comunes","area":"Ortografia i gramàtica · B2.1","section":"grammar21","exercises":[{"id":"t21-ex1","number":"21.1","title":"El meu registre d’errades","type":"open","book":true,"quadern":true,"solutionKind":"guide","bodyHtml":"","responseFields":[{"label":"1","question":"Errada 1: forma correcta · forma incorrecta · exemple · explicació"},{"label":"2","question":"Errada 2: forma correcta · forma incorrecta · exemple · explicació"},{"label":"3","question":"Errada 3: forma correcta · forma incorrecta · exemple · explicació"},{"label":"4","question":"Errada 4: forma correcta · forma incorrecta · exemple · explicació"},{"label":"5","question":"Errada 5: forma correcta · forma incorrecta · exemple · explicació"},{"label":"6","question":"Errada 6: forma correcta · forma incorrecta · exemple · explicació"},{"label":"7","question":"Errada 7: forma correcta · forma incorrecta · exemple · explicació"},{"label":"8","question":"Errada 8: forma correcta · forma incorrecta · exemple · explicació"},{"label":"9","question":"Errada 9: forma correcta · forma incorrecta · exemple · explicació"},{"label":"10","question":"Errada 10: forma correcta · forma incorrecta · exemple · explicació"},{"label":"11","question":"Errada 11: forma correcta · forma incorrecta · exemple · explicació"},{"label":"12","question":"Errada 12: forma correcta · forma incorrecta · exemple · explicació"}],"solutionHtml":"<p>Resposta personal. Revisa cada entrada amb una font normativa o amb la professora. L’objectiu és explicar la correcció i evitar repetir l’errada.</p>"}],"theoryHtml":"<section class=\"card theory book-content\"><h2>Teoria</h2><ul><li>Utilitza aquest registre per identificar les errades que repeteixes i recordar-ne la correcció.</li><li>Anota la forma correcta, la incorrecta, un exemple complet i la regla que t’ajuda a recordar-la.</li></ul><div class=\"rule\"><h3>Exemples</h3><ul><li>Correcte: havia. Incorrecte: habia. Exemple: Havia acabat. Regla: haver s’escriu amb v.</li></ul></div></section>"}];